{
  "packet_id": "H6-T03-2",
  "claim_id": "C043",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C043.component",
    "value": "An attachment alone does not establish that the approval was valid.",
    "scope": "Attachment presence by itself; the mapping does not define validity criteria in this span.",
    "provenance": {
      "refs": [
        {
          "source_id": "P030",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P030 explicitly states the attachment-alone restriction on establishing validity."
    }
  },
  "signal_basis": {
    "component_id": "C043.signal_basis",
    "value": "Cross-checks assess order identity and approval scope, while independently originating records establish agreement about the approver's authority and the particular approval. Delegation alone does not establish approval of an order.",
    "scope": "The described checks and signal are assumed for this judgment; the mapping presents them as possible findings, not completed observations.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
