        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the substantive cross-checks, authority limitation, corroborating signal and prospective status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C043.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The bounded claim is supported without an unresolved empirical relation."
    }
  },
  "rationale": "Attachment presence alone does not establish the approver's authority or that the approval covers the identified order. The mapping's checks therefore license this limited insufficiency claim. It does not assert that an attached approval is invalid.",
  "uncertainty": "The validity of any particular approval remains case-dependent; that does not undermine the attachment-alone limitation.",
  "anomalies": []
}
